const experiences = [
  {
    company: "Department of Home Affairs",
    role: "Full Stack Web Developer",
    description:
      "Participated in the design, development and testing of the E-Exit System. Developed and maintained application features using C#, Blazor and .NET.",
    technologies: ["C#", "Blazor", ".NET", "SQL"],
  },
  {
    company: "Department of Justice & Constitutional Development",
    role: "IT Coordinator",
    description:
      "Worked with Business Analysis, Change Requests, SAP, Remedy and DevOps while supporting internal systems.",
    technologies: ["Business Analysis", "SAP", "Remedy", "DevOps"],
  },
];

export default function Experience() {
  return (
    <section className="bg-success py-5 text-white">
      <div className="container">

        <h2 className="text-center mb-5 fw-bold">Experience</h2>

        <div className="row">

          {/* Timeline */}
          <div className="col-2 position-relative d-flex justify-content-center">

            {/* Vertical Line */}
            <div
              className="position-absolute bg-white"
              style={{
                width: "4px",
                height: "100%",
                left: "50%",
                transform: "translateX(-50%)",
              }}
            ></div>

            {/* Timeline Dots */}
            <div className="d-flex flex-column justify-content-around h-100">
              {experiences.map((_, index) => (
                <div
                  key={index}
                  className="bg-white border border-3 border-success rounded"
                  style={{
                    width: "35px",
                    height: "35px",
                    zIndex: 2,
                  }}
                ></div>
              ))}
            </div>

          </div>

          {/* Experience Content */}
          <div className="col-10">

            {experiences.map((exp, index) => (
              <div className="mb-5" key={index}>

                <h3 className="fw-bold">
                  {exp.company} ({exp.role})
                </h3>

                <p>{exp.description}</p>

                <p>
                  <strong>Technologies:</strong>{" "}
                  {exp.technologies.join(", ")}
                </p>

                <div className="d-flex gap-3 mt-3">
                  {exp.technologies.map((tech, i) => (
                    <div
                      key={i}
                      className="bg-light rounded"
                      style={{
                        width: "60px",
                        height: "60px",
                      }}
                    ></div>
                  ))}
                </div>

              </div>
            ))}

          </div>

        </div>
      </div>
    </section>
    );
    }
